const tidyTex = s => s
  .replace(/\{1(?=[xt]\})/g, '{')
  .replace(/(^|[^0-9.,{}a-zA-Z\\^_])1(?=[xykt](?![a-zA-Z]))/g, '$1')
  .replace(/\+\s*-\s*(?=[0-9a-zA-Z\\(])/g, '- ')
  .replace(/([^-<!])--(?=[0-9a-zA-Z\\(])/g, '$1+');
const tidyAny = v => typeof v === 'string' ? tidyTex(v) : Array.isArray(v) ? v.map(tidyAny) : v;
for (const id in GEN) GEN[id] = GEN[id].map(g => r => {
  const tk = g(r);
  for (const k of ['q', 'steps', 'hint', 'opts', 'ans']) if (tk[k] != null) tk[k] = tidyAny(tk[k]);
  if (tk.fields) tk.fields.forEach(f => { if (typeof f.label === 'string') f.label = tidyTex(f.label); });
  return tk;
});
